INSERT OR IGNORE INTO `kai_query_templates`
	(`intent`, `purpose`, `required_data`, `query_logic`)
VALUES
	('SALES_CURRENT', 'ยอดขาย Sales ในช่วงวันที่กำหนด', 'sales_transactions.company_id, sale_date, product_type, quantity', 'SELECT SUM(quantity) AS sales_unit FROM sales_transactions WHERE company_id = :company_id AND sale_date >= :start_date AND sale_date < :end_date AND normalized product_type IN (TT, CH, EX, TP)'),
	('SALES_VALUE_CURRENT', 'มูลค่า Sales ในช่วงวันที่กำหนด', 'sales_transactions.company_id, sale_date, final_received', 'SELECT SUM(CAST(final_received AS REAL)) AS sales_value FROM sales_transactions WHERE company_id = :company_id AND sale_date >= :start_date AND sale_date < :end_date AND final_received IS NOT NULL'),
	('SALES_MONTH_COMPARE', 'เปรียบเทียบ Sales ระหว่างเดือนปัจจุบันและเดือนก่อน', 'sales_transactions.sale_date, quantity, final_received', 'Run SALES001 and SALES002 for :current_start/:current_end and :previous_start/:previous_end; calculate difference and Growth % outside SQL'),
	('SALES_YOY_COMPARE', 'เปรียบเทียบเดือนเดียวกันคนละปี', 'sales_transactions.sale_date, quantity, final_received', 'Run SALES001 and SALES002 for :current_year/:month and :comparison_year/:month; keep both periods explicit'),
	('SALES_HISTORY_QUERY', 'ตอบยอด Sales ของเดือนและปีที่ระบุ', 'sales_transactions.sale_date, quantity, final_received', 'WHERE company_id = :company_id AND strftime(''%Y'', sale_date) = :year AND strftime(''%m'', sale_date) = printf(''%02d'', :month)'),
