	('SALES_GROWTH_QUERY', 'คำนวณ Growth ระหว่างสองผลลัพธ์', 'current_value, comparison_value', '(current_value - comparison_value) / comparison_value * 100; return N/A when comparison_value is zero or missing'),
	('BOOKING_CURRENT', 'ยอด Booking ในช่วงเวลา', 'booking_transactions.company_id, booking_date, booking_no', 'SELECT COUNT(*) AS booking_unit FROM booking_transactions WHERE company_id = :company_id AND booking_date >= :start_date AND booking_date < :end_date'),
	('BOOKING_VALUE_CURRENT', 'มูลค่า Booking ในช่วงเวลา', 'booking_transactions.booking_date, booking_price', 'SELECT SUM(CAST(booking_price AS REAL)) AS booking_value FROM booking_transactions WHERE company_id = :company_id AND booking_date >= :start_date AND booking_date < :end_date AND booking_price IS NOT NULL'),
