	('STOCK_SLOW_MOVING_QUERY', 'นับ Stock อายุเกิน 180 วัน', 'stock_age_days, stock_status, kmm_flag', 'Apply STOCK_CURRENT scope and WHERE stock_age_days > 180'),
	('STOCK_SLOW_MOVING_MODEL_RANKING', 'จัดอันดับรุ่น Slow Moving', 'product_model, stock_age_days, physical identifiers', 'Apply STOCK_SLOW_MOVING_QUERY, GROUP BY product_model, ORDER BY COUNT(*) DESC'),
	('STOCK_MODEL_QUERY', 'ตอบ Stock ของรุ่นที่ระบุ', 'product_model, stock_status, physical identifiers', 'Apply STOCK_CURRENT scope and exact canonical model filter; return count and value with source scope');
